// Auto-generated priprema-za-nastavu HTML for Nivo 1 lessons.
// Backfilled into ilmihal_lekcije.content_html on server startup if missing.
export const NIVO1_PRIPREME: Record<string,string> = {
  "uvodna-rijec": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Vjeronauka</p>\n        <p><strong>Nastavna jedinica:</strong> Uvodna riječ – upoznavanje sa mektebom</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema mektebu, druženju i učenju o vjeri</p>\n      <p><strong>Obrazovni cilj:</strong> Upoznati učenike sa mektebom, muallimom i pravilima ponašanja</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje pozitivnog stava prema vjerskoj pouci</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Es-selamu alejkum, draga djeco! Dobro došli u mekteb. Hajde da se prvo upoznamo. Ja sam vaš/a muallim/a, a vi mi recite kako se zovete. Da li znate šta je mekteb i zašto smo ovdje?</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Mekteb je kuća za učenje vjere u kojoj djeca uče o Allahu, Poslaniku Muhammedu, a.s., i lijepom ponašanju.</p><p>U mektebu učimo Kur’an, dove, sure, ilmihal i mnoge druge korisne stvari.</p><p>Razgovaram sa djecom o tome šta očekuju od mekteba, koje stvari su čuli kod kuće, te ih ohrabrujem da slobodno postavljaju pitanja.</p><p>Objašnjavam pravila ponašanja: pažljivo slušamo, dižemo ruku kad želimo nešto reći, lijepo se odnosimo prema svima.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Pitam djecu šta su naučili na ovom času i kako se osjećaju u mektebu. Najavljujem da ćemo na sljedećem času početi učiti prve dove.</p>\n    </div>\n  </div>\n</div>",
  "kako-pocinjem-posao": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ahlak</p>\n        <p><strong>Nastavna jedinica:</strong> Kako počinjemo svaki dobar posao</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje navike spominjanja Allaha prije svakog posla</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti učenike da svaki dobar posao počinju Bismillom i dovom</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvoj svijesti o stalnoj povezanosti sa Stvoriteljem</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kada krećete u školu, kada jedete ili kada legnete spavati – kažete li nešto prije toga? Kakav osjećaj imate kad nešto započnete sa lijepim riječima?</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Musliman svaki dobar posao započinje učenjem Bismille: <em>Bismillahi-r-Rahmani-r-Rahim</em> – U ime Allaha, Milostivog, Samilosnog.</p><p>Time tražimo Allahovu pomoć i bereket u onome što radimo.</p><p>Pored Bismille, lijepo je proučiti i kratku dovu (npr. Rabbi jessir) kojom molimo Allaha da nam olakša posao.</p><p>Postupak: Pišem na tabli Bismillu sa značenjem. Učenici je ponavljaju nekoliko puta. Razgovaramo o prilikama u kojima se uči (prije jela, ulaska u kuću, polaska u školu, učenja, putovanja).</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju situacije u kojima će ubuduće učiti Bismillu. Zajedno učimo Bismillu još jednom, glasno i pravilno.</p>\n    </div>\n  </div>\n</div>",
  "covjek-najljepse-stvorenje": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Akaid</p>\n        <p><strong>Nastavna jedinica:</strong> Čovjek je najljepše Allahovo stvorenje</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje zahvalnosti Allahu na blagodatima i darovima</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti da je čovjek najodabranije Allahovo stvorenje, počašćeno razumom</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje samopoštovanja i poštovanja drugih ljudi</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Pogledajte oko sebe – životinje, biljke, planine, more. Sve je to Allah stvorio. A ko je, prema Kur’anu, najljepše Allahovo stvorenje? Hajde da to danas otkrijemo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Allah, dž.š., je stvorio čovjeka u najljepšem obliku i dao mu razum kojim razlikuje dobro od zla.</p><p>Čovjek se po tome razlikuje od svih drugih stvorenja: zna govoriti, učiti, raditi, donositi odluke.</p><p>Allah od nas traži da budemo zahvalni na svemu – na zdravlju, vidu, sluhu, porodici i pameti.</p><p>Razgovor: Šta sve mogu moje oči, uši, ruke, srce? Kako se zahvaljujemo Allahu? (kroz dove, namaz, lijepa djela)</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju blagodati za koje su zahvalni. Zaključujemo da svako od nas treba čuvati ono što mu je Allah dao i koristiti to za dobro.</p>\n    </div>\n  </div>\n</div>",
  "ja-idem-u-mekteb": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ahlak</p>\n        <p><strong>Nastavna jedinica:</strong> Ja idem u mekteb</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema dolasku u mekteb i druženju u njemu</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti pravila ponašanja u mektebu i odnosa prema muallimu i drugovima</p>\n      <p><strong>Funkcionalni cilj:</strong> Stvaranje navike redovnog dolaska u mekteb</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kako ste se pripremili za današnji dolazak u mekteb? Šta osjećate kad uđete u učionicu? Hajde da razgovaramo o tome zašto rado dolazimo u mekteb.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Mekteb je posebno mjesto gdje učimo o Allahu, Kur’anu i lijepom ponašanju.</p><p>Prije dolaska treba se umiti, lijepo obući i ponijeti potrebne knjige i pribor.</p><p>U mekteb ulazimo sa selamom, pozdravljamo muallima i drugove, sjedamo mirno i pažljivo slušamo.</p><p>Prema muallimu se odnosimo s poštovanjem, prema drugovima sa ljubavlju, a knjige i učionicu čuvamo čistim.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici sami nabrajaju lijepe navike koje će primjenjivati pri dolasku u mekteb. Pohvaljujem one koji već dolaze redovno i uredno.</p>\n    </div>\n  </div>\n</div>",
  "dova-za-znanje": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Kiraet</p>\n        <p><strong>Nastavna jedinica:</strong> Dova za znanje – Rabbi zidni ‘ilmen</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema znanju i učenju</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti dovu kojom molimo Allaha da nam poveća znanje</p>\n      <p><strong>Funkcionalni cilj:</strong> Stvaranje navike učenja dove prije sticanja znanja</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, šta radimo kad nešto želimo, a sami ne možemo postići? – Pitamo nekog ko može pomoći. Pa hajde da i mi za znanje, koje je najveći dar, zamolimo Allaha.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Dova za znanje glasi: <em>Rabbi zidni ‘ilmen</em> – Gospodaru moj, povećaj mi znanje!</p><p>Ovu dovu nas je naučio sam Allah, dž.š., u Kur’anu (sura Ta-ha, 114).</p><p>Učimo je prije početka učenja, prije časa u školi i mektebu, te kad god želimo nešto novo naučiti.</p><p>Postupak: Pišem dovu na tabli sa značenjem. Učimo je više puta, glasno i pravilno. Učenici je ponavljaju zajedno i pojedinačno.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Provjeravam ko je naučio dovu napamet. Dogovaramo se da je svaki dan učimo prije početka časa.</p>\n    </div>\n  </div>\n</div>",
  "nasa-vjera": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Akaid</p>\n        <p><strong>Nastavna jedinica:</strong> Kako se zove naša vjera</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi i ponosa prema vjeri islamu</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti naziv vjere, sljedbenika i njene osnovne karakteristike</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje svijesti o vlastitom vjerskom identitetu</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, ko vas je naučio prvim riječima o Allahu? Šta su vam roditelji rekli – koja je naša vjera? Hajde danas to lijepo da utvrdimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Naša vjera se zove <strong>islam</strong>.</p><p>Sljedbenici islama nazivaju se <strong>muslimani</strong> i <strong>muslimanke</strong>.</p><p>Riječ \"islam\" znači predanost Allahu, a \"musliman\" je onaj koji se predaje Allahovoj volji.</p><p>Naša vjera nas uči da vjerujemo u jednog Allaha i da je Muhammed, a.s., Allahov posljednji poslanik. Naša sveta knjiga je Kur’an.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Pitam učenike: Kako se zove naša vjera? Kako se zovu njeni sljedbenici? U koga vjerujemo? Pohvaljujem tačne odgovore.</p>\n    </div>\n  </div>\n</div>",
  "allahu-rabbi": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Kiraet</p>\n        <p><strong>Nastavna jedinica:</strong> Allahu Rabbi – ilahija</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema ilahijama i spominjanju Allahovog imena</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti riječi i melodiju ilahije \"Allahu Rabbi\"</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje muzičkog osjećaja i pamćenja kroz pjesmu</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, volite li pjevati? Postoje posebne pjesme koje muslimani pjevaju u slavu Allaha – zovu se ilahije. Danas učimo jednu kratku i lijepu ilahiju.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Ilahija \"Allahu Rabbi\" pjeva o tome da je Allah naš Gospodar, a Muhammed, a.s., naš poslanik.</p><p>Postupak: Učim ilahiju nekoliko puta sam, polako i razgovijetno. Zatim učenici ponavljaju stih po stih.</p><p>Razgovaram s djecom o tome šta znače riječi: Allahu Rabbi (Allah je moj Gospodar), Muhammed Nebijji (Muhammed je moj Vjerovjesnik).</p><p>Ilahiju učimo u različitim prilikama: kod kuće, u mektebu, na priredbama.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici zajedno pjevaju cijelu ilahiju. Pohvaljujem trud i najavljujem ponavljanje na sljedećem času.</p>\n    </div>\n  </div>\n</div>",
  "zuri-mirza-na-pouku": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ahlak</p>\n        <p><strong>Nastavna jedinica:</strong> Žuri Mirza na pouku – pjesma o redovnosti</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema redovnom dolasku u mekteb</p>\n      <p><strong>Obrazovni cilj:</strong> Razumjeti poruku pjesme i primijeniti je u svom životu</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje navike tačnosti i odgovornosti</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, znate li nekog drugara koji uvijek dolazi na vrijeme i radostan je što ide u mekteb? Hajde da upoznamo Mirzu iz naše pjesmice.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Pjesma \"Žuri Mirza na pouku\" govori o dječaku koji rado i na vrijeme dolazi u mekteb da bi učio o vjeri.</p><p>Pjesmu čitam izražajno, a učenici slušaju. Zatim je čitamo zajedno.</p><p>Razgovor: Zašto Mirza žuri u mekteb? Kako se vi pripremate za dolazak? Šta nas čeka u mektebu?</p><p>Učenici stih po stih ponavljaju, a najbolje pamtitelji recituju pred razredom.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici recituju strofe pjesme. Dogovaramo se da i mi, poput Mirze, redovno i radosno dolazimo u mekteb.</p>\n    </div>\n  </div>\n</div>",
  "kelimei-sehadet-1": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Akaid</p>\n        <p><strong>Nastavna jedinica:</strong> Kelimei-šehadet – prvi islamski šart</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje svijesti o pripadnosti islamu i ponosa zbog vjerovanja</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti pravilno izgovoriti i razumjeti značenje kelimei-šehadeta</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje navike čestog izgovaranja šehadeta</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Es-selamu alejkum, djeco. Ko od vas zna kako se zove naša vjera? A kako, nekim posebnim riječima, izjavljujemo da smo muslimani? Te riječi danas učimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Kelimei-šehadet su riječi kojima izjavljujemo i svjedočimo da smo muslimani.</p><p>Kelimei-šehadet glasi: <em>Ešhedu en lā ilāhe illallāh, ve ešhedu enne Muhammeden ‘abduhū ve resūluhū.</em></p><p>Značenje: Vjerujem i izjavljujem da je samo Allah Bog, i vjerujem i izjavljujem da je Muhammed Allahov rob i poslanik.</p><p>Šehadet je prvi islamski šart. Izgovara ga svako ko prima islam, a muslimani ga ponavljaju u namazu i u mnogim drugim prilikama.</p><p>Postupak: Pišem šehadet na tabli arapski i sa transkripcijom. Učim ga polako, naglašavajući svaku riječ. Učenici ga ponavljaju zajedno i pojedinačno. Ispravljam izgovor.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Provjeravam ko je naučio šehadet napamet. Učenici recituju i pjesmicu \"Šehadet\". Najavljujem da ćemo sljedeći čas učiti o ostalim islamskim šartima.</p>\n    </div>\n  </div>\n</div>",
  "voda-izvor-zivota": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Akaid</p>\n        <p><strong>Nastavna jedinica:</strong> Voda je izvor života</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje zahvalnosti Allahu na blagodati vode</p>\n      <p><strong>Obrazovni cilj:</strong> Razumjeti važnost vode za sav život i njenu ulogu u islamu</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje navike štednje i čuvanja vode</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, šta bi se desilo da nemamo vode? Možemo li bez nje? Hajde danas razgovarati o ovom velikom Allahovom daru.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Allah, dž.š., u Kur’anu kaže da je od vode svako živo biće stvoreno (sura El-Enbija, 30).</p><p>Voda je potrebna za piće, čistoću tijela, abdest i gusul, te za biljke i životinje.</p><p>Bez vode nema života – ona je jedna od najvećih Allahovih blagodati.</p><p>Razgovor: Kako se zahvaljujemo Allahu na vodi? Treba li je rasipati? Kako se ponašamo kada uzimamo abdest – štedimo li vodu?</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju gdje sve koristimo vodu. Dogovaramo se da je čuvamo i ne rasipamo, jer je to ibadet i znak zahvalnosti.</p>\n    </div>\n  </div>\n</div>",
  "allah-dz-s": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Akaid</p>\n        <p><strong>Nastavna jedinica:</strong> Allah, dž.š. – Svemogući Stvoritelj</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi i strahopoštovanja prema Allahu</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti da je Allah jedan, Stvoritelj svega i Gospodar svih svjetova</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje svijesti da je Allah uvijek prisutan i sve zna</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, ko je stvorio nebo, sunce, zvijezde i nas? Ko nam daje hranu, zdravlje, roditelje? Hajde danas da naučimo nešto više o našem Stvoritelju.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Naš Bog se zove <strong>Allah</strong>. On je jedan, jedini, nema druga ni saučesnika.</p><p>Allah je Stvoritelj svega što postoji – nas, životinja, biljaka, planeta i čitavog svemira.</p><p>Kad god spomenemo Allahovo ime, lijepo je dodati <em>dželle šanuhu</em> (uzvišen je) ili kratko <em>dž.š.</em></p><p>Allah sve vidi, sve čuje i sve zna – i ono što govorimo i ono što mislimo.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Pitam: Ko je stvorio sve? Kako spominjemo Allahovo ime? Učenici odgovaraju, a ja pohvaljujem ispravne odgovore.</p>\n    </div>\n  </div>\n</div>",
  "muhammed-as-poslanik": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Akaid</p>\n        <p><strong>Nastavna jedinica:</strong> Muhammed, a.s., je naš poslanik</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema Allahovom Poslaniku, a.s.</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti osnovne podatke o Muhammedu, a.s., i njegovoj ulozi</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje navike donošenja salavata na Poslanika</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, koju knjigu je Allah, dž.š., poslao muslimanima? Preko koga? Danas govorimo o tome ko je Muhammed, a.s., i zašto ga toliko volimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Muhammed, a.s., je posljednji Allahov poslanik. Allah ga je poslao da nas pouči vjeri.</p><p>Rođen je u Mekki, a Allahov govor (Kur’an) primao je preko meleka Džibrila.</p><p>Kad god spomenemo njegovo ime, donesemo salavat: <em>sallallahu ‘alejhi ve sellem</em> (s.a.v.s.) ili <em>alejhis-selam</em> (a.s.).</p><p>Muhammed, a.s., je bio najljepšeg ahlaka – iskren, milostiv, pravedan – i on je naš najveći uzor.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici ponavljaju: Ko je Muhammed, a.s.? Šta kažemo kad spomenemo njegovo ime? Učimo zajedno: <em>Allahumme salli ‘alā Muhammed.</em></p>\n    </div>\n  </div>\n</div>",
  "hasbi-rabbi": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Kiraet</p>\n        <p><strong>Nastavna jedinica:</strong> Hasbi Rabbi – ilahija/dova</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema spominjanju Allaha i Poslanika, a.s.</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti riječi ilahije \"Hasbi Rabbi\"</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti memorisanja i lijepog učenja</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kome se obraćamo kada nam je teško? Ko nam je uvijek dovoljan? Hajde danas naučiti jednu prelijepu ilahiju kojom to izričemo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Ilahija glasi: <em>Hasbi Rabbi džellallah, ma fi kalbi gajrullah, nūr Muhammed sallallah, lā ilāhe illallah.</em></p><p>Značenje: Dovoljan mi je Gospodar moj, Uzvišeni Allah; u mom srcu nema nikog osim Allaha; svjetlost je Muhammed, neka je Allahov salavat na njega; nema boga osim Allaha.</p><p>Postupak: Učim ilahiju polako stih po stih. Učenici ponavljaju zajedno i pojedinačno. Pažnju usmjeravam na pravilan izgovor.</p><p>Razgovor: Šta nam ova ilahija poručuje o našem odnosu prema Allahu i Poslaniku, a.s.?</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici zajedno uče cijelu ilahiju. Najboljima dajem priliku da je samostalno prouče pred razredom.</p>\n    </div>\n  </div>\n</div>",
  "islamski-sarti-1": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Akaid</p>\n        <p><strong>Nastavna jedinica:</strong> Islamski šarti – pet stubova islama</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje svijesti o značaju glavnih islamskih dužnosti</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti pet islamskih šarta po redoslijedu</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti pamćenja i nabrajanja</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, zamislite veliku zgradu na pet stubova. Ako bilo koji stub fali, zgrada se ruši. Tako je i sa našom vjerom – ima pet stubova, koje danas učimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Islamski šarti su glavne islamske dužnosti koje treba izvršavati svaki punoljetni musliman i muslimanka.</p><p>Ima ih pet: <strong>1) kelimei-šehadet, 2) namaz, 3) post, 4) zekat, 5) hadž.</strong></p><p>Prva tri šarta odnose se na svakog muslimana, a zekat i hadž samo na one koji to mogu i imaju mogućnosti.</p><p>Postupak: Pišem šarte na tabli po redoslijedu. Učenici ih ponavljaju zajedno više puta. Pojedinačno provjeravam ko ih zna nabrojati.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Pitam: Koliko ima islamskih šarta? Koji je prvi? Koji drugi? Učenici nabrajaju, a ja pohvaljujem.</p>\n    </div>\n  </div>\n</div>",
  "namaz-1": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Namaz – stub vjere</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema namazu i navike njegovog obavljanja</p>\n      <p><strong>Obrazovni cilj:</strong> Razumjeti šta je namaz i zašto ga klanjamo</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje navike redovnog klanjanja</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kako se zahvaljujemo nekome ko nam je učinio dobro? Allah nam svaki dan daje toliko blagodati – kako Mu mi to vraćamo? Najljepši način je – namazom.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Namaz je drugi islamski šart i stub vjere.</p><p>Klanjajući namaz, mi se zahvaljujemo Allahu na svemu što nam daje: zdravlju, hrani, roditeljima, životu.</p><p>Poslanik, a.s., je rekao: \"Namaz je radost mog oka.\"</p><p>Namaz nas čini smirenim, sretnim i boljim ljudima jer kroz njega razgovaramo sa Allahom.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Razgovaramo o tome ko od učenika već klanja kod kuće sa roditeljima. Pohvaljujem one koji to čine i podstičem druge da pokušaju.</p>\n    </div>\n  </div>\n</div>",
  "abdeski-sarti": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Abdeski šarti – farzovi abdesta</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje pažnje i odgovornosti pri uzimanju abdesta</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti četiri farza (šarta) abdesta</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti pravilnog uzimanja abdesta</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, ko od vas zna uzeti abdest? Šta od abdesta je obavezno – tj. mora se uraditi da bi abdest bio ispravan? Hajde danas naučiti abdeske šarte.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Abdeski šarti (farzovi) su dijelovi abdesta bez kojih abdest nije ispravan. Ima ih četiri:</p><p><strong>1.</strong> oprati cijelo lice,</p><p><strong>2.</strong> oprati ruke do iznad laktova,</p><p><strong>3.</strong> potrati (mesh) jednu četvrtinu glave,</p><p><strong>4.</strong> oprati noge do iznad članaka.</p><p>Postupak: Pišem šarte na tabli po redu. Demonstriram svaki pokret. Učenici ih ponavljaju i pokazuju mjesta na sebi. Naglašavam da ako neki od farza propustimo, abdest nije ispravan.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Provjeravam ko je naučio sva četiri šarta. Učenici redom nabrajaju. Najavljujem vježbu uzimanja abdesta na sljedećem času.</p>\n    </div>\n  </div>\n</div>",
  "ezan": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Ezan – poziv na namaz</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema ezanu i džamiji</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti riječi ezana i njihovo značenje</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje navike pažljivog slušanja ezana</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, šta čujemo pet puta dnevno sa munare? Ko ga uči? Šta nam taj poziv govori? Hajde danas naučiti riječi ezana.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Ezan je poziv kojim se muslimani pozivaju na namaz. Uči ga muezzin sa munare.</p><p>Riječi ezana glase: <em>Allahu ekber (4×), Ešhedu en lā ilāhe illallāh (2×), Ešhedu enne Muhammeden resūlullāh (2×), Hajje ‘ales-salāh (2×), Hajje ‘alel-felāh (2×), Allahu ekber (2×), Lā ilāhe illallāh.</em></p><p>U sabahskom ezanu, poslije \"Hajje ‘alel-felāh\", dodaje se: <em>Es-salātu hajrun mine-n-nevm</em> (Namaz je bolji od sna).</p><p>Postupak: Pišem ezan na tabli sa transkripcijom i prijevodom. Puštam snimak ezana. Učenici slušaju i ponavljaju.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Razgovor: Šta osjećamo kada čujemo ezan? Kako se ponašamo dok ezan uči? Pohvaljujem one koji su zapamtili dijelove.</p>\n    </div>\n  </div>\n</div>",
  "ikamet": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Ikamet – poziv pred početak namaza</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje pažnje i ozbiljnosti pred početak namaza</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti razliku između ezana i ikameta i riječi ikameta</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti pravilnog izgovora arapskih riječi</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, znamo da nas ezan poziva na namaz. A kako se zove poziv kojim počinjemo sam namaz u džematu? To je ikamet, koji danas učimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Ikamet se uči neposredno pred početak farz-namaza, kad se klanja u džematu.</p><p>Riječi ikameta su slične ezanu, samo se uči brže i tiše, te se dodaje: <em>Kad kāmeti-s-salāh (2×)</em> – Eto, namaz je počeo.</p><p>Razlika ezan/ikamet: ezan poziva ljude izdaleka, a ikamet je znak da klanjači stanu u sufove i počnu namaz.</p><p>Postupak: Pišem riječi ikameta na tabli. Puštam snimak. Učenici uče zajedno. Ispravljam izgovor.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Provjeravam: Šta je ezan, a šta ikamet? Kada se uči ikamet? Učenici odgovaraju, a ja pohvaljujem.</p>\n    </div>\n  </div>\n</div>",
  "dova-poslije-ezana": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Kiraet</p>\n        <p><strong>Nastavna jedinica:</strong> Dova poslije ezana</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema Poslaniku, a.s., i navike učenja dova</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti dovu koja se uči odmah poslije ezana</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti pamćenja kratkih dova</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, šta uradimo nakon što čujemo ezan? Da li samo idemo dalje, ili kažemo nešto posebno? Danas učimo dovu koja se uči poslije ezana.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Kada čujemo ezan, lijepo je tiho ponavljati riječi za muezzinom, a nakon završenog ezana proučiti dovu.</p><p>Dova glasi: <em>Allahumme Rabbe hāzihi-d-da‘veti-t-tāmmeh, ve-s-salāti-l-kā’imeh, āti Muhammeden el-vesīlete vel-fadīleh, veb‘ashu mekāmen mahmūden ellezī ve‘adteh.</em></p><p>Značenje: Allahu, Gospodaru ovog savršenog poziva i namaza koji se uspostavlja, podari Muhammedu počasno mjesto i odlikovanje, te ga proživi na hvaljenom položaju koji si mu obećao.</p><p>Postupak: Pišem dovu na tabli, s transkripcijom i prijevodom. Učimo je polako, dio po dio. Učenici ponavljaju.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici uče dovu napamet, dio po dio. Dogovaramo se da je svaki put kad čujemo ezan učimo.</p>\n    </div>\n  </div>\n</div>",
  "odredjivanje-kible": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Orijentacija i određivanje kible</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje svijesti o povezanosti svih muslimana kroz Kabu</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je kibla i kako je odrediti</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje praktične sposobnosti orijentacije u prostoru</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kad muslimani klanjaju, svi se okreću u istom pravcu. Šta mislite, prema čemu? Hajde danas da naučimo kako se taj pravac određuje.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Kibla je pravac prema Kabi u Mekki, prema kojem se okrećemo u namazu.</p><p>U našim krajevima (Bosna i Hercegovina) kibla je u pravcu jugoistoka.</p><p>Kibla se može odrediti na više načina: pomoću Sunca (zalazak je na zapadu), kompasa, mobilnih aplikacija ili praćenjem kible u džamijama.</p><p>Postupak: Pokazujem na karti gdje je Mekka. Pomoću kompasa pokazujem pravac kible u učionici. Učenici se okreću prema kibli.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Pitam: Šta je kibla? U kojem pravcu je iz naših krajeva? Kako je možemo odrediti? Učenici odgovaraju.</p>\n    </div>\n  </div>\n</div>",
  "namaski-ruknovi-2": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Namaski ruknovi (II dio)</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje pažnje i ozbiljnosti pri obavljanju namaza</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti preostale namaske ruknove</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti pravilnog obavljanja namaza</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, prošlog časa smo počeli učiti namaske ruknove – stvari koje se obavezno čine u namazu. Ko se sjeća prvih? Danas učimo i preostale.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Namaski ruknovi su radnje koje se obavezno čine u namazu. U II dijelu učimo:</p><p><strong>Sedžda</strong> – padanje na sedždu sa sedam dijelova tijela (čelo s nosom, dvije šake, dva koljena, prsti obje noge).</p><p><strong>Ka’da</strong> (sjedenje) – sjedenje na kraju namaza pri učenju Et-tehijatu.</p><p><strong>Predaja selama</strong> – završetak namaza okretanjem glave desno i lijevo uz riječi <em>Es-selamu alejkum ve rahmetullāh.</em></p><p>Postupak: Pokazujem svaki rukn praktično. Učenici ponavljaju. Naglašavam da bez ovih ruknova namaz nije potpun.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju sve namaske ruknove (I i II dio). Provjeravam praktičnim pokazivanjem.</p>\n    </div>\n  </div>\n</div>",
  "gusulski-sarti": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Gusulski šarti – farzovi gusula</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje navike čistoće tijela</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je gusul i tri njegova farza</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje znanja za pravilno obavljanje gusula</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, ponekad nije dovoljno samo uzeti abdest – treba se okupati na poseban način. To kupanje zovemo gusul. Šta je obavezno pri gusulu? Hajde da naučimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Gusul je obavezno kupanje cijelog tijela u određenim prilikama (npr. nakon sna iz kojeg se sanja…, prije Bajram-namaza poželjno).</p><p>Gusulski šarti (farzovi) su tri:</p><p><strong>1.</strong> isprati usta vodom,</p><p><strong>2.</strong> isprati nos vodom,</p><p><strong>3.</strong> oprati cijelo tijelo, tako da nigdje ne ostane suho mjesto.</p><p>Postupak: Pišem šarte na tabli. Razgovaram o važnosti čistoće u islamu. Naglašavam da Poslanik, a.s., kaže: \"Čistoća je pola vjere.\"</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju tri gusulska šarta. Pitanje: Koja Poslanikova izreka govori o čistoći? Pohvaljujem.</p>\n    </div>\n  </div>\n</div>",
  "tejemumski-sarti": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Tejemumski šarti – zamjena za abdest i gusul</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje svijesti o olakšicama u islamu</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je tejemum i kada se uzima</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje znanja o postupanju u posebnim situacijama</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, šta će uraditi musliman koji nema vode, a vrijeme namaza je nastupilo? Allah je dao olakšicu – tejemum. Šta je to, danas učimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Tejemum je čišćenje suhom čistom zemljom (ili pijeskom) kao zamjena za abdest ili gusul kada nema vode ili je voda štetna za zdravlje.</p><p>Tejemumski šarti su:</p><p><strong>1.</strong> nijet (namjera) za tejemum,</p><p><strong>2.</strong> udariti dlanovima po čistoj zemlji i potrati lice,</p><p><strong>3.</strong> ponovo udariti dlanovima i potrati ruke do iznad laktova.</p><p>Postupak: Demonstriram tejemum praktično. Učenici ponavljaju pokrete. Naglašavam da se tejemum uzima samo kad nema vode ili je voda nedostupna/štetna.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Pitam: Šta je tejemum? Kada se uzima? Učenici odgovaraju i pokazuju pokrete.</p>\n    </div>\n  </div>\n</div>",
  "pravila-ponasanja": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ahlak</p>\n        <p><strong>Nastavna jedinica:</strong> Islamska pravila ponašanja</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje lijepog ahlaka i ponašanja u svakodnevnom životu</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti osnovna islamska pravila ponašanja</p>\n      <p><strong>Funkcionalni cilj:</strong> Primjena pravila ponašanja u različitim situacijama</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, koje su to lijepe stvari koje radimo svaki dan, a koje pokazuju da smo dobro odgojeni? Hajde danas razgovarati o islamskim pravilima ponašanja.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Islam nas uči lijepom ponašanju u svakoj situaciji. Neka osnovna pravila su:</p><p><strong>1.</strong> nazvati selam pri susretu i pri ulasku u kuću ili učionicu,</p><p><strong>2.</strong> proučiti Bismillu prije svakog dobrog posla,</p><p><strong>3.</strong> jesti i piti desnom rukom, sjedeći,</p><p><strong>4.</strong> poštivati starije i biti milostiv prema mlađima,</p><p><strong>5.</strong> govoriti istinu i ne psovati,</p><p><strong>6.</strong> čuvati čistoću tijela, odjeće i okoliša.</p><p>Razgovor: Koja od ovih pravila već primjenjujemo? Koja možemo poboljšati?</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici sami nabrajaju pravila i daju primjere iz svog života. Dogovaramo se da svako sebi izabere jedno pravilo na kojem će raditi.</p>\n    </div>\n  </div>\n</div>",
  "mubarek-dani": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Vjeronauka</p>\n        <p><strong>Nastavna jedinica:</strong> Muslimanski mubarek dani</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje radosti i poštovanja prema vjerskim praznicima</p>\n      <p><strong>Obrazovni cilj:</strong> Upoznati učenike sa značajnim danima u islamu</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje svijesti o vjerskoj tradiciji</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, koje praznike slavimo u našoj porodici? Koji je najradosniji dan u godini? Danas učimo o našim vjerskim mubarek danima.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Mubarek znači blagoslovljen, a mubarek dani su posebno vrijedni dani u islamu.</p><p>Najpoznatiji mubarek dani su: <strong>Ramazanski bajram, Kurban-bajram, Lejletul-Kadr, Mevlud, Lejletul-Bera’et, Lejletul-Mi’radž, Lejletu-r-Regaib</strong> i nova hidžretska godina.</p><p>U te dane se posebno klanja, uči Kur’an, donose salavati, posjećuju rodbina i komšije, i čine dobra djela.</p><p>Razgovor: Koje smo mubarek dane već proslavili u porodici? Kako ih najljepše proslaviti?</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju mubarek dane. Pohvaljujem one koji su zapamtili veći broj.</p>\n    </div>\n  </div>\n</div>",
  "ramazanski-bajram": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Vjeronauka</p>\n        <p><strong>Nastavna jedinica:</strong> Radost Ramazanskog bajrama</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje radosti i zahvalnosti zbog dolaska Bajrama</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je Ramazanski bajram i kako se proslavlja</p>\n      <p><strong>Funkcionalni cilj:</strong> Upoznati osnovne bajramske običaje</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, koji je dan najradosniji nakon mjeseca ramazana? Šta uradite ujutro na taj dan? Hajde da razgovaramo o ljepoti Ramazanskog bajrama.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Ramazanski bajram nastupa prvi dan ševvala – odmah nakon završetka mjeseca ramazana. Traje tri dana.</p><p>Tog dana se klanja Bajram-namaz u džamiji, dijeli se sadekatu-l-fitr siromašnima, posjećuju roditelji, rodbina i komšije.</p><p>Lijepo je obući novu ili čistu odjeću, namirisati se, čestitati Bajram riječima: <em>Bajram šerif mubarek olsun!</em> – odgovor: <em>Allah razi olsun!</em></p><p>Razgovor: Kako vi proslavljate Bajram? Koga prvo posjetite? Šta najviše volite na taj dan?</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici prepričavaju svoje bajramske doživljaje. Dogovaramo se da Bajram dočekamo kao istinski praznik – sa namazom, sadakom i radošću.</p>\n    </div>\n  </div>\n</div>",
  "kurban-bajram": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Vjeronauka</p>\n        <p><strong>Nastavna jedinica:</strong> Radost Kurban-bajrama</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje žrtve, dijeljenja i pomaganja drugima</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je Kurban-bajram i šta je kurban</p>\n      <p><strong>Funkcionalni cilj:</strong> Upoznati običaje vezane za Kurban-bajram</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, da li ste čuli za priču o poslaniku Ibrahimu, a.s., i njegovom sinu Ismailu? Šta je Allah od njega tražio? Danas govorimo o Kurban-bajramu.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Kurban-bajram nastupa 10. dana mjeseca zul-hidže i traje četiri dana.</p><p>Tog dana se klanja Bajram-namaz, a oni koji to mogu kolju kurban (ovcu, kozu, govedo) – u sjećanje na žrtvu Ibrahima, a.s.</p><p>Meso kurbana se dijeli na tri dijela: jedan za porodicu, jedan za rodbinu i prijatelje, jedan za siromašne.</p><p>U te dane se obavlja i hadž – muslimani iz cijelog svijeta posjećuju Kabu u Mekki.</p><p>Razgovor: Šta nas Kurban-bajram uči? – žrtvu, dijeljenje, brigu za one koji nemaju.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju razlike između Ramazanskog i Kurban-bajrama. Pohvaljujem trud i znanje.</p>\n    </div>\n  </div>\n</div>",
  "za-bajram-je-pohvalno": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ahlak</p>\n        <p><strong>Nastavna jedinica:</strong> Za Bajram je lijepo i pohvalno</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema bajramskim sunnetima</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je sunnet i pohvalno činiti za Bajram</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje navike pripreme za Bajram</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kako se vi pripremate za Bajram? Šta uradite uvečer prije Bajrama, a šta ujutro? Hajde da naučimo šta je za Bajram pohvalno raditi.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Za Bajram je lijepo i pohvalno (sunnet) sljedeće:</p><p><strong>1.</strong> rano ustati i okupati se (uzeti gusul),</p><p><strong>2.</strong> obući lijepu i čistu odjeću,</p><p><strong>3.</strong> namirisati se,</p><p><strong>4.</strong> pojesti nešto slatko prije Bajram-namaza (na Ramazanski bajram),</p><p><strong>5.</strong> u džamiju i iz džamije ići različitim putevima,</p><p><strong>6.</strong> donositi tekbire i salavate,</p><p><strong>7.</strong> čestitati Bajram poznanicima i nepoznatima.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju bajramske sunnete. Dogovaramo se da na sljedećem Bajramu primijenimo sve što smo naučili.</p>\n    </div>\n  </div>\n</div>",
  "nova-hidzretska-godina": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Vjeronauka</p>\n        <p><strong>Nastavna jedinica:</strong> Nova hidžretska godina</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje svijesti o islamskoj historiji</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je hidžretska godina i kako je nastala</p>\n      <p><strong>Funkcionalni cilj:</strong> Upoznati način računanja vremena u islamu</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, znate da postoji naša \"obična\" godina koja počinje 1. januara. Ali postoji i druga, posebna godina koju koriste muslimani. Kako se zove i kada počinje?</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Hidžretska godina je islamska godina koja se računa od preseljenja (hidžre) Poslanika, a.s., iz Mekke u Medinu (622. godine po miladu).</p><p>Prvi mjesec u hidžretskoj godini je <strong>muharrem</strong>. Kada nastupi 1. muharrem, to je nova hidžretska godina.</p><p>Godina se računa po kretanju mjeseca, pa hidžretska godina ima oko 354 dana – kraća je od miladske za oko 11 dana.</p><p>Hidžra je bila važan događaj jer je Poslanik, a.s., u Medini osnovao prvu islamsku zajednicu i izgradio prvu džamiju.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Pitam: Od kojeg događaja počinje hidžretska godina? Koji je prvi mjesec? Učenici odgovaraju.</p>\n    </div>\n  </div>\n</div>",
  "mevlud": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Vjeronauka</p>\n        <p><strong>Nastavna jedinica:</strong> Mevlud – sjećanje na rođenje Poslanika, a.s.</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema Poslaniku, a.s.</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti šta je mevlud i kada se obilježava</p>\n      <p><strong>Funkcionalni cilj:</strong> Upoznati tradiciju proslave mevluda</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kako se osjećate kad neko od vaših drugara ima rođendan? A da li znate kada je rođen najdraži čovjek svim muslimanima – Muhammed, a.s.?</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Mevlud je sjećanje na rođenje Allahovog Poslanika Muhammeda, a.s.</p><p>Poslanik, a.s., rođen je u Mekki, 12. dana mjeseca rebi’ul-evvela.</p><p>Mevlud se proslavlja u džamijama i kućama – uče se ilahije i kaside, donose salavati i prepričava život Poslanika, a.s.</p><p>Kod nas je posebno poznat Mevlud Hafiza Saliha Gaševića pisan na bosanskom jeziku.</p><p>Razgovor: Jeste li bili na mevludu? Koje ste ilahije čuli? Kako se osjećate kad slušate o životu Poslanika, a.s.?</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učimo zajedno salavat: <em>Allahumme salli ‘alā Muhammed.</em> Dogovaramo se da na mevlud donosimo što više salavata.</p>\n    </div>\n  </div>\n</div>",
  "dobro-nam-dos-o": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Kiraet</p>\n        <p><strong>Nastavna jedinica:</strong> Dobro nam doš’o – ilahija o ramazanu</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje radosti zbog dolaska mjeseca ramazana</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti riječi ilahije \"Dobro nam doš’o\"</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje muzičkog osjećaja kroz ilahije</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kako dočekujemo dragog gosta u našoj kući? A koji nam to mjesec dolazi jednom godišnje, kao najdraži gost? Hajde danas naučiti ilahiju kojom ga dočekujemo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Ilahija \"Dobro nam doš’o\" pjeva o radosti zbog dolaska mjeseca ramazana – mjeseca posta, Kur’ana i milosti.</p><p>Postupak: Učim ilahiju polako, stih po stih. Učenici slušaju, zatim ponavljaju zajedno.</p><p>Razgovor: Šta nam ramazan donosi? Zašto smo radosni kad dođe? Šta posebno radimo u tom mjesecu? (post, teravije, učenje Kur’ana, sehur, iftar)</p><p>Učenici uče ilahiju i razgovaraju o ljepotama ramazana.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici zajedno pjevaju ilahiju. Pohvaljujem trud i podstičem ih da je nauče napamet do dolaska ramazana.</p>\n    </div>\n  </div>\n</div>",
  "pet-dnevnih-namaza": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ibadat</p>\n        <p><strong>Nastavna jedinica:</strong> Pet dnevnih namaza</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje svijesti o važnosti redovnog obavljanja namaza</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti imena pet dnevnih namaza i njihova okvirna vremena</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti prepoznavanja vremena namaza</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, koliko puta dnevno čujemo ezan? Šta to znači? Allah nam je propisao pet susreta sa Njim svaki dan – pet namaza, koje danas učimo.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>U toku jednog dana i noći klanja se pet farz-namaza:</p><p><strong>1. Sabah</strong> – od zore do pred izlazak Sunca,</p><p><strong>2. Podne</strong> – kad Sunce prođe sredinu neba do kasnog popodneva,</p><p><strong>3. Ikindija</strong> – kad Sunce nagne zapadu do pred zalazak,</p><p><strong>4. Akšam</strong> – odmah nakon zalaska Sunca, do potpunog mraka,</p><p><strong>5. Jacija</strong> – nakon što potpuno padne mrak, do pred zoru.</p><p>Postupak: Pišem nazive namaza na tabli. Pomoću slike sata pokazujem približna vremena. Učenici nabrajaju namaze.</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Provjeravam: Koliko ima dnevnih namaza? Nabroji ih po redu. Kada je sabah, a kada akšam? Učenici odgovaraju.</p>\n    </div>\n  </div>\n</div>",
  "ajetul-kursija": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Kiraet</p>\n        <p><strong>Nastavna jedinica:</strong> Ajetul-Kursija</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje ljubavi prema Kur’anu i učenju njegovih ajeta</p>\n      <p><strong>Obrazovni cilj:</strong> Naučiti tekst i značenje Ajetul-Kursije</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje sposobnosti memorisanja dužih kur’anskih tekstova</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, koji je najveći ajet u Kur’anu? Poslanik, a.s., je rekao da onaj ko ga uči poslije svakog farz-namaza ne razdvaja ga od Dženneta osim smrti. To je Ajetul-Kursija.</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Ajetul-Kursija je 255. ajet sure El-Bekare. Govori o veličini i moći Allaha, dž.š.</p><p>U njemu se spominje da Allah nikoga ne ostavlja bez nadgledanja, da Mu ne sustiže ni san ni drijem, te da Njegova vlast obuhvata nebesa i Zemlju.</p><p>Postupak: Učim ajet polako, dio po dio, naglašavajući svaku riječ. Učenici ponavljaju zajedno i pojedinačno. Pišem ajet na tabli s transkripcijom.</p><p>Razgovor: Šta nam ovaj ajet poručuje o Allahovoj veličini? Kada se uči? (poslije svakog farz-namaza, prije spavanja, kao zaštita).</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici uče ajet u dijelovima. Najboljima dajem priliku da prouče naučeni dio. Najavljujem nastavak učenja na sljedećem času.</p>\n    </div>\n  </div>\n</div>",
  "sport": "<div class=\"lesson-accordion\">\n  <button class=\"lesson-section-btn\" onclick=\"toggleSection('priprema', this)\">\n    PRIPREMA ZA NASTAVU <span class=\"section-icon\">▼</span>\n  </button>\n  <div id=\"priprema\" class=\"lesson-content\" style=\"display: none;\">\n    <div class=\"lesson-text\">\n      <div style=\"background: #f0fdf4; border-left: 4px solid #16a34a; padding: 16px; border-radius: 8px; margin-bottom: 16px;\">\n        <p><strong>Predmet:</strong> Ahlak</p>\n        <p><strong>Nastavna jedinica:</strong> Sport i rekreacija</p>\n        <p><strong>Tip sata:</strong> Obrada novog gradiva</p>\n      </div>\n      <h3>Ciljevi nastavnog sata</h3>\n      <p><strong>Odgojni cilj:</strong> Razvijanje navike brige o tijelu i zdravlju</p>\n      <p><strong>Obrazovni cilj:</strong> Razumjeti odnos islama prema sportu i tjelesnoj aktivnosti</p>\n      <p><strong>Funkcionalni cilj:</strong> Razvijanje aktivnog načina života</p>\n      <h3>Organizacija nastave</h3>\n      <p><strong>Oblici rada:</strong> Frontalni, individualni</p>\n      <p><strong>Nastavna sredstva:</strong> Udžbenik, tabla, kreda</p>\n      <p><strong>Nastavne metode:</strong> Metoda usmenog izlaganja, demonstrativna metoda, razgovor</p>\n      <hr style=\"border: none; border-top: 2px solid #14b8a6; margin: 20px 0;\">\n      <h3 style=\"background: #f0fdfa; border-left: 4px solid #14b8a6; padding: 10px 16px; border-radius: 8px; color: #0f766e; margin-top: 16px;\">📋 Struktura sata</h3>\n      <h4 style=\"background: #eff6ff; border-left: 4px solid #3b82f6; padding: 8px 14px; border-radius: 6px; color: #1d4ed8; margin-top: 12px;\">🔵 Uvodni dio</h4>\n      <p>Djeco, kojim se sportovima bavite? Volite li trčati, plivati, jahati? Šta mislite, šta islam kaže o sportu i kretanju?</p>\n      <h4 style=\"background: #f0fdf4; border-left: 4px solid #22c55e; padding: 8px 14px; border-radius: 6px; color: #15803d; margin-top: 12px;\">🟢 Glavni dio</h4>\n      <p>Islam nas uči da je tijelo emanet (povjerenje) od Allaha i da o njemu trebamo brinuti.</p><p>Poslanik, a.s., preporučivao je svojim drugovima: gađanje strijelom, jahanje konja i plivanje – aktivnosti koje jačaju tijelo i pripremaju za život.</p><p>Sport i rekreacija nas čine zdravijim, jačim i vedrijim, ali pri tome ne smijemo zanemariti ibadete i obaveze.</p><p>Razgovor: Koje sportove vi volite? Kako možemo balansirati između sporta, učenja i namaza? Šta nije dozvoljeno (npr. okladovi, nasilje, nepristojna odjeća)?</p>\n      <h4 style=\"background: #fefce8; border-left: 4px solid #eab308; padding: 8px 14px; border-radius: 6px; color: #a16207; margin-top: 12px;\">🟡 Završni dio</h4>\n      <p>Učenici nabrajaju koristi sporta. Dogovaramo se da uz sport ne zaboravimo na namaz, učenje i lijepo ponašanje.</p>\n    </div>\n  </div>\n</div>"
};
